script:
uprobe:libc:getaddrinfo
{
  printf("%s pid=%d node=%s service=%s\n", comm, pid, str(arg0), str(arg1));
}

tracepoint:syscalls:sys_enter_openat
{
  printf("%s pid=%d file=%s\n", comm, pid, str(args->filename));
}

tracepoint:sched:sched_process_exec
{
  printf("pid=%d comm=%s exec=%s\n", args->pid, comm, str(args->filename));
}

software:page-faults
{
  @faults[comm] = count();
  @total = count();
}

END
{
  print(@faults);
  print(@total);
  clear(@faults);
  clear(@total);
}

tracepoint:block:block_rq_issue
{
  @start[args->dev, args->sector] = nsecs;
  @who[args->dev, args->sector] = comm;
}
tracepoint:block:block_rq_complete
/@start[args->dev, args->sector]/
{
  $lat_ms = (nsecs - @start[args->dev, args->sector]) / 1000000;
  if ($lat_ms >= 10) {
    @slow[@who[args->dev, args->sector]] = count();
  }
  delete(@start[args->dev, args->sector]);
  delete(@who[args->dev, args->sector]);
}
END
{
  clear(@start);
  clear(@who);
  print(@slow);
  clear(@slow);
}

